import{_ as i,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"S3select: Computational Storage in S3","description":"","frontmatter":{"title":"S3select: Computational Storage in S3","date":"2022-11-14T00:00:00.000Z","updated":"2022-11-15T00:00:00.000Z","tags":["[S3 Select]","[数据存储]","[SQL查询]","[性能优化]","[AWS服务]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/S3select_-_Computational_Storage_in_S3.md","filePath":"posts/2022/S3select_-_Computational_Storage_in_S3.md","lastUpdated":1780459816000}'),o={name:"posts/2022/S3select_-_Computational_Storage_in_S3.md"};function S(r,l,s,n,p,u){return t(),e("div",null,[...l[0]||(l[0]=[a('<p>Gar Salomon 在会议上介绍了 S3 Select 的概念、工作原理、优势以及未来的发展方向。S3 Select 是 AWS S3 的一种新能力，允许客户端将 SQL 语句推送到存储层，从而只提取所需的数据，提高性能并降低成本。</p><h3 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h3><ol><li><p><strong>S3 Select 简介</strong></p><ul><li>引入时间：2020年7月</li><li>功能：允许客户端推送 SQL 语句到存储层</li><li>优势：提高性能，减少成本</li></ul></li><li><p><strong>为什么需要 S3 Select</strong></p><ul><li>传统方法：数据移动到操作地点</li><li>S3 Select 方法：操作推送到数据附近</li><li>优势：减少内存消耗，优化大数据生态系统</li></ul></li><li><p><strong>S3 Select 的工作原理</strong></p><ul><li>集成到 GET 对象模型中</li><li>对象被获取并由 S3 Select 模型处理每个片段</li><li>支持格式：CSV, JSON, Parquet</li></ul></li><li><p><strong>SQL 在机器学习中的作用</strong></p><ul><li>SQL 是处理数据的主要语言</li><li>数据必须格式化以供机器学习算法使用</li></ul></li><li><p><strong>S3 Select 的软件设计特点</strong></p><ul><li>引擎设计：头文件代码，单文件函数，内存高效使用</li><li>数据类型处理：不同数据类型的读取器与 SQL 引擎解耦</li></ul></li><li><p><strong>数据类型处理流程</strong></p><ul><li>CSV：简单格式，不支持数据类型</li><li>JSON：支持数据类型和模式</li><li>Parquet：高级对象，包含元数据，支持直接访问特定数据</li></ul></li><li><p><strong>并行处理和优化</strong></p><ul><li>通过分割数据范围并行处理查询</li><li>未来可能集成到 Spark, Presto 等分析应用中</li></ul></li><li><p><strong>验证和测试</strong></p><ul><li>表达式生成器：生成复杂表达式以验证引擎</li><li>SQL 生成器：生成复杂 SQL 语句以测试系统</li></ul></li><li><p><strong>未来工作</strong></p><ul><li>集成 S3 Select 到 Spark, Presto 等分析应用中</li><li>优化方向：作为优化器，提高查询性能</li></ul></li><li><p><strong>开发和测试</strong></p><ul><li>继续开发和测试 S3 Select 的功能</li><li>探索与现有分析应用的集成可能性</li></ul></li></ol><h3 id="关键词保留" tabindex="-1">关键词保留 <a class="header-anchor" href="#关键词保留" aria-label="Permalink to &quot;关键词保留&quot;">​</a></h3><ul><li>[S3 Select]</li><li>[数据存储]</li><li>[SQL查询]</li><li>[性能优化]</li><li>[AWS服务]</li><li>[Parquet]</li><li>[CSV]</li><li>[JSON]</li><li>[Spark]</li><li>[Presto]</li></ul><h3 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h3><ul><li>原总结中缺少了对数据类型处理流程的详细描述，如 CSV、JSON 和 Parquet。</li><li>原总结中未提及 S3 Select 的软件设计特点，如头文件代码和单文件函数。</li><li>原总结中未提及 S3 Select 的验证和测试方法，如表达式生成器和 SQL 生成器。</li><li>原总结中未提及 S3 Select 的未来工作，如集成到 Spark 和 Presto。</li></ul>',7)])])}const g=i(o,[["render",S]]);export{_ as __pageData,g as default};
